def solve() -> int:
    chicken_price = 10
    chicken_weight = 40
    if chicken_weight > 50:
      discount = 0.1 * chicken_weight
      total_price = chicken_price * chicken_weight - discount
    else:
      total_price = chicken_price * chicken_weight
    result = total_price
    return result

def solve() -> int:
